#include <iostream>
#include <cmath>
#include <limits>
#include <algorithm>

int main() {
    int t1, t2, x1, x2, s, tram_pos;
    int dir;

    std::cin >> s >> x1 >> x2 >> t1 >> t2 >> tram_pos >> dir;

    dir = std::max(dir, 0);

    const int walking = std::abs(x1 - x2) * t2;

    int tram_to_x2 = std::numeric_limits<int>::max();
    int tram_to_x1 = std::numeric_limits<int>::max();

    int x = -x2;
    int y = -x1;

    if ((x - tram_pos >= 0) == dir) {
        tram_to_x2 = std::min(tram_to_x2, std::abs(x - tram_pos) * t1);
    }
    if ((y - tram_pos >= 0) == dir) {
        tram_to_x1 = std::min(tram_to_x1, std::abs(y - tram_pos) * t1);
    }

    x = x2;
    y = x1;

    if ((x - tram_pos >= 0) == dir) {
        tram_to_x2 = std::min(tram_to_x2, std::abs(x - tram_pos) * t1);
    }
    if ((y - tram_pos >= 0) == dir) {
        tram_to_x1 = std::min(tram_to_x1, std::abs(y - tram_pos) * t1);
    }

    x = 2 * s - x2;
    y = 2 * s - x1;

    if ((x - tram_pos >= 0) == dir) {
        tram_to_x2 = std::min(tram_to_x2, std::abs(x - tram_pos) * t1);
    }
    if ((y - tram_pos >= 0) == dir) {
        tram_to_x1 = std::min(tram_to_x1, std::abs(y - tram_pos) * t1);
    }

    if (tram_to_x1 <= tram_to_x2) {
        std::cout << std::min(tram_to_x2, walking) << '\n';
    } else {
        int added_time;
        if (x1 < x2) {
            added_time = (x1 + x2) * t1;
        } else {
            added_time = (2 * s - x1 - x2) * t1;
        }

        std::cout << std::min(tram_to_x1 + added_time, walking) << '\n';
    }

    return 0;
}

