int main() {
    long long s, x1, x2, t1, t2, tramPos;
    int dir;

    std::cin >> s >> x1 >> x2 >> t1 >> t2 >> tramPos >> dir;

    const long long distance = std::abs(x1 - x2);
    const long long walkingTime = distance * t2;

    long long waitDistance;

    if (tramPos == x1) {
        waitDistance = 0;
    } else if ((dir == 1 && tramPos < x1) ||
               (dir == -1 && tramPos > x1)) {
        waitDistance = std::abs(tramPos - x1);
    } else if (dir == 1) {
        waitDistance = (s - tramPos) + (s - x1);
    } else {
        waitDistance = tramPos + x1;
    }

    const long long tramTime = (waitDistance + distance) * t1;
    std::cout << std::min(walkingTime, tramTime) << '\n';

    return 0;
}

#include <iostream>
#include <algorithm>
#include <cstdlib>

int main() {
    long long s, x1, x2, t1, t2, tramPos;
    int direction;

    std::cin >> s >> x1 >> x2 >> t1 >> t2 >> tramPos >> direction;

    const long long period = 2 * s;
    const long long initialPhase =
        (direction == 1) ? tramPos : period - tramPos;

    auto nextVisit = [period](long long position, long long phase) {
        long long result = phase + period;

        for (long long residue : {position, period - position}) {
            long long candidate = residue;
            if (candidate < phase) {
                candidate += ((phase - candidate + period - 1) / period) * period;
            }
            result = std::min(result, candidate);
        }

        return result;
    };

    const long long pickupPhase = nextVisit(x1, initialPhase);
    const long long arrivalPhase = nextVisit(x2, pickupPhase);

    const long long walkingTime = std::llabs(x1 - x2) * t2;
    const long long tramTime = (arrivalPhase - initialPhase) * t1;

    std::cout << std::min(walkingTime, tramTime) << '\n';

    return 0;
}

